// Service Worker for the Spraak-agenda (TEC-07: everything works offline).
// Generated by scripts/build-sw.mjs, which fills in the version and the file list.
//
// Strategy: "cache first". All app files are stored on the phone at install;
// after that they are always served from the phone, with or without internet.
// The Service Worker never sends anything anywhere: it only answers requests
// for our own files (SEC-01).

const VERSION = "__VERSION__";
const BASE_PATH = "__BASE_PATH__";
const CACHE = `app-${VERSION}`;
const URLS = __URLS__;

// 1. Install: store every app file.
self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(URLS))
      .then(() => self.skipWaiting()), // use the new version on the next app start
  );
});

// 2. Activate: remove app files of older versions (the model cache is kept).
self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key.startsWith("app-") && key !== CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

// 3. Fetch: answer from the phone's storage when we have the file.
self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== "GET" || url.origin !== self.location.origin) return;

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      // Pages are stored without the query string (?…).
      const cached = await cache.match(event.request, { ignoreSearch: event.request.mode === "navigate" });
      if (cached && event.request.destination === "worker") {
        // A worker takes its address from the response. The stored copy has
        // no "#params=…" part, which the Whisper worker needs to start. A fresh
        // copy without an address makes the worker keep the original one.
        return new Response(await cached.blob(), { headers: cached.headers });
      }
      if (cached) return cached;
      try {
        return await fetch(event.request);
      } catch (error) {
        // Offline and not stored: for page loads, show the start page.
        if (event.request.mode === "navigate") {
          const start = await cache.match(`${BASE_PATH}/`);
          if (start) return start;
        }
        throw error;
      }
    })(),
  );
});
